import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  output: 'standalone',
  poweredByHeader: false,
  // Passenger may run several app processes, and each one keeps its own
  // in-memory copy of the incremental cache. Reading from disk only keeps the
  // file system cache authoritative, so a page regenerated by one process is
  // immediately served by all of them.
  cacheMaxMemorySize: 0,
}

export default nextConfig
